from pysat.solvers import Glucose3

solver = Glucose3()
n = 25
colors = 4

def var(v, c):
    return v * colors + c + 1

for v in range(n):
    solver.add_clause([var(v, c) for c in range(colors)])
    for c1 in range(colors):
        for c2 in range(c1+1, colors):
            solver.add_clause([-var(v, c1), -var(v, c2)])

for u, v in edges:
    for c in range(colors):
        solver.add_clause([-var(u, c), -var(v, c)])

print("Colorable:", solver.solve())

