def get_shortest_cycle(edges, n):
    from collections import deque
    shortest_cycle = None
    min_len = 100

    adj = {i: [] for i in range(n)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(n):
        dist = {i: 0}
        parent = {i: -1}
        q = deque([i])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
