def girth(edges, n):
    adj = {i: [] for i in range(n)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_girth = float('inf')
    for i in range(n):
        dist = {i: 0}
        q = [i]
        parent = {i: -1}
        while q:
            u = q.pop(0)
